1	import { Gradient } from '../gradient/Gradient';
2	import { Group } from '../shapes/Group';
3	import { FabricImage } from '../shapes/Image';
4	import { classRegistry } from '../ClassRegistry';
5	import {
6	  invertTransform,
7	  multiplyTransformMatrices,
8	  qrDecompose,
9	} from '../util/misc/matrix';
10	import { removeTransformMatrixForSvgParsing } from '../util/transform_matrix_removal';
11	import type { FabricObject } from '../shapes/Object/FabricObject';
12	import { Point } from '../Point';
13	import { CENTER, FILL, STROKE } from '../constants';
14	import { getGradientDefs } from './getGradientDefs';
15	import { collectSheetRules } from './collectSheetRules';
16	import type { LoadImageOptions } from '../util';
17	import type { CSSRules, TSvgReviverCallback } from './typedefs';
18	import type { ParsedViewboxTransform } from './applyViewboxTransform';
19	import type { SVGOptions } from '../gradient';
20	import { getTagName } from './getTagName';
21	import { parseTransformAttribute } from './parseTransformAttribute';
22	
23	const findTag = (el: Element) =>
24	  classRegistry.getSVGClass(getTagName(el).toLowerCase());
25	
26	type StorageType = {
27	  fill: SVGGradientElement;
28	  stroke: SVGGradientElement;
29	  clipPath: Element[];
30	};
31	
32	type NotParsedFabricObject = FabricObject & {
33	  fill: string;
34	  stroke: string;
35	  clipPath?: string;
36	  clipRule?: CanvasFillRule;
37	};
38	
39	export class ElementsParser {
40	  declare elements: Element[];
41	  declare options: LoadImageOptions & ParsedViewboxTransform;
42	  declare reviver?: TSvgReviverCallback;
43	  declare regexUrl: RegExp;
44	  declare doc: Document;
45	  declare clipPaths: Record<string, Element[]>;
46	  declare gradientDefs: Record<string, SVGGradientElement>;
47	  declare cssRules: CSSRules;
48	
49	  constructor(
50	    elements: Element[],
51	    options: LoadImageOptions & ParsedViewboxTransform,
52	    reviver: TSvgReviverCallback | undefined,
53	    doc: Document,
54	    clipPaths: Record<string, Element[]>,
55	  ) {
56	    this.elements = elements;
57	    this.options = options;
58	    this.reviver = reviver;
59	    this.regexUrl = /^url\(['"]?#([^'"]+)['"]?\)/g;
60	    this.doc = doc;
61	    this.clipPaths = clipPaths;
62	    this.gradientDefs = getGradientDefs(doc);
63	    this.cssRules = collectSheetRules(doc);
64	  }
65	
66	  parse(): Promise<Array<FabricObject | null>> {
67	    return Promise.all(
68	      this.elements.map((element) => this.createObject(element)),
69	    );
70	  }
71	
72	  async createObject(el: Element): Promise<FabricObject | null> {
73	    const klass = findTag(el);
74	    if (klass) {
75	      const obj: NotParsedFabricObject = await klass.fromElement(
76	        el,
77	        this.options,
78	        this.cssRules,
79	      );
80	      this.resolveGradient(obj, el, FILL);
81	      this.resolveGradient(obj, el, STROKE);
82	      if (obj instanceof FabricImage && obj._originalElement) {
83	        removeTransformMatrixForSvgParsing(
84	          obj,
85	          obj.parsePreserveAspectRatioAttribute(),
86	        );
87	      } else {
88	        removeTransformMatrixForSvgParsing(obj);
89	      }
90	      await this.resolveClipPath(obj, el);
91	      this.reviver && this.reviver(el, obj);
92	      return obj;
93	    }
94	    return null;
95	  }
96	
97	  extractPropertyDefinition(
98	    obj: NotParsedFabricObject,
99	    property: 'fill' | 'stroke' | 'clipPath',
100	    storage: Record<string, StorageType[typeof property]>,
101	  ): StorageType[typeof property] | undefined {
102	    const value = obj[property]!,
103	      regex = this.regexUrl;
104	    if (!regex.test(value)) {
105	      return undefined;
106	    }
107	    // verify: can we remove the 'g' flag? and remove lastIndex changes?
108	    regex.lastIndex = 0;
109	    // we passed the regex test, so we know is not null;
110	    const id = regex.exec(value)![1];
111	    regex.lastIndex = 0;
112	    // @todo fix this
113	    return storage[id];
114	  }
115	
116	  resolveGradient(
117	    obj: NotParsedFabricObject,
118	    el: Element,
119	    property: 'fill' | 'stroke',
120	  ) {
121	    const gradientDef = this.extractPropertyDefinition(
122	      obj,
123	      property,
124	      this.gradientDefs,
125	    ) as SVGGradientElement;
126	    if (gradientDef) {
127	      const opacityAttr = el.getAttribute(property + '-opacity');
128	      const gradient = Gradient.fromElement(gradientDef, obj, {
129	        ...this.options,
130	        opacity: opacityAttr,
131	      } as SVGOptions);
132	      obj.set(property, gradient);
133	    }
134	  }
135	
136	  // TODO: resolveClipPath could be run once per clippath with minor work per object.
137	  // is a refactor that i m not sure is worth on this code
138	  async resolveClipPath(
139	    obj: NotParsedFabricObject,
140	    usingElement: Element,
141	    exactOwner?: Element,
142	  ) {
143	    const clipPathElements = this.extractPropertyDefinition(
144	      obj,
145	      'clipPath',
146	      this.clipPaths,
147	    ) as Element[];
148	    if (clipPathElements) {
149	      const objTransformInv = invertTransform(obj.calcTransformMatrix());
150	      const clipPathTag = clipPathElements[0].parentElement!;
151	      let clipPathOwner = usingElement;
152	      while (
153	        !exactOwner &&
154	        clipPathOwner.parentElement &&
155	        clipPathOwner.getAttribute('clip-path') !== obj.clipPath
156	      ) {
157	        clipPathOwner = clipPathOwner.parentElement;
158	      }
159	      // move the clipPath tag as sibling to the real element that is using it
160	      clipPathOwner.parentElement!.appendChild(clipPathTag);
161	
162	      // this multiplication order could be opposite.
163	      // but i don't have an svg to test it
164	      // at the first SVG that has a transform on both places and is misplaced
165	      // try to invert this multiplication order
166	      const finalTransform = parseTransformAttribute(
167	        `${clipPathOwner.getAttribute('transform') || ''} ${
168	          clipPathTag.getAttribute('originalTransform') || ''
169	        }`,
170	      );
171	
172	      clipPathTag.setAttribute(
173	        'transform',
174	        `matrix(${finalTransform.join(',')})`,
175	      );
176	
177	      const container = await Promise.all(
178	        clipPathElements.map((clipPathElement) => {
179	          return findTag(clipPathElement)
180	            .fromElement(clipPathElement, this.options, this.cssRules)
181	            .then((enlivedClippath: NotParsedFabricObject) => {
182	              removeTransformMatrixForSvgParsing(enlivedClippath);
183	              enlivedClippath.fillRule = enlivedClippath.clipRule!;
184	              delete enlivedClippath.clipRule;
185	              return enlivedClippath;
186	            });
187	        }),
188	      );
189	      const clipPath =
190	        container.length === 1 ? container[0] : new Group(container);
191	      const gTransform = multiplyTransformMatrices(
192	        objTransformInv,
193	        clipPath.calcTransformMatrix(),
194	      );
195	      if (clipPath.clipPath) {
196	        await this.resolveClipPath(
197	          clipPath,
198	          clipPathOwner,
199	          // this is tricky.
200	          // it tries to differentiate from when clipPaths are inherited by outside groups
201	          // or when are really clipPaths referencing other clipPaths
202	          clipPathTag.getAttribute('clip-path') ? clipPathOwner : undefined,
203	        );
204	      }
205	      const { scaleX, scaleY, angle, skewX, translateX, translateY } =
206	        qrDecompose(gTransform);
207	      clipPath.set({
208	        flipX: false,
209	        flipY: false,
210	      });
211	      clipPath.set({
212	        scaleX,
213	        scaleY,
214	        angle,
215	        skewX,
216	        skewY: 0,
217	      });
218	      clipPath.setPositionByOrigin(
219	        new Point(translateX, translateY),
220	        CENTER,
221	        CENTER,
222	      );
223	      obj.clipPath = clipPath;
224	    } else {
225	      // if clip-path does not resolve to any element, delete the property.
226	      delete obj.clipPath;
227	      return;
228	    }
229	  }
230	}
