import { ruleSelectorTest } from './ruleSelectorTest';
import { doesSomeParentMatch } from './doesSomeParentMatch';

/**
 * @private
 */

export function elementMatchesRule(
  element: HTMLElement | SVGElement,
  selectors: string[],
) {
  let parentMatching = true;
  // start from rightmost selector.
  const firstMatching = ruleSelectorTest(element, selectors.pop()!);
  if (firstMatching && selectors.length) {
    parentMatching = doesSomeParentMatch(element, selectors);
  }
  return firstMatching && parentMatching && selectors.length === 0;
}

