import { describe, it, expect } from 'vitest';
import { loadSVGFromString } from './loadSVGFromString';
import '../../fabric';
import { collectSheetRules } from './collectSheetRules';
import { getFabricDocument } from '../env';

describe('repro', () => {
  it('multi-style multi-class', async () => {
    const svg = `<svg xmlns="http://www.w3.org/2000/svg">
<style>
.blue { fill: blue; }
</style>
<style>
.red { fill: url(https://example.com/paint.svg#swatch); }
</style>
<circle class="blue" r="45" cx="50" cy="50"></circle>
<circle class="red" r="45" cx="150" cy="50"></circle>
</svg>`;
    const result = await loadSVGFromString(svg);
    console.log('fills', result.objects.map((o: any) => o && o.fill));

    const doc = new DOMParser().parseFromString(svg, 'text/xml');
    console.log('cssRules', JSON.stringify(collectSheetRules(doc)));
    const styleEls = doc.getElementsByTagName('style');
    console.log('style count', styleEls.length);
    for (let i = 0; i < styleEls.length; i++) {
      console.log('style', i, JSON.stringify(styleEls[i].textContent));
    }
  });
});

