import { describe, it, expect } from 'vitest';
import { loadSVGFromString } from './loadSVGFromString';
import '../../fabric';

describe('repro', () => {
  it('original example from prompt: two style elements, each with its own class', async () => {
    const svg = `<svg xmlns="http://www.w3.org/2000/svg">
<style>
.blue { fill: blue; }
</style>
<style>
.red { fill: red; }
</style>
<circle class="blue" r="45" cx="50" cy="50"></circle>
<circle class="red" r="45" cx="150" cy="50"></circle>
</svg>`;
    const result = await loadSVGFromString(svg);
    expect(result.objects[0]!.fill).toBe('blue');
    expect(result.objects[1]!.fill).toBe('red');
  });

  it('handles fill referencing a paint server url with colons', async () => {
    const svg = `<svg xmlns="http://www.w3.org/2000/svg">
<style>
.blue { fill: blue; }
</style>
<style>
.red { fill: url(https://example.com/paint.svg#swatch); }
</style>
<circle class="blue" r="45" cx="50" cy="50"></circle>
<circle class="red" r="45" cx="150" cy="50"></circle>
</svg>`;
    const result = await loadSVGFromString(svg);
    expect(result.objects[0]!.fill).toBe('blue');
    expect(result.objects[1]!.fill).toBe(
      'url(https://example.com/paint.svg#swatch)',
    );
  });

  it('handles a shape carrying more than one class, rules split across style elements', async () => {
    const svg = `<svg xmlns="http://www.w3.org/2000/svg">
<style>
.blue { fill: blue; }
</style>
<style>
.bold { stroke-width: 5; }
</style>
<circle class="blue bold" r="45" cx="50" cy="50"></circle>
</svg>`;
    const result = await loadSVGFromString(svg);
    expect(result.objects[0]!.fill).toBe('blue');
    expect((result.objects[0] as any).strokeWidth).toBe(5);
  });
});

